#include <iostream>
#include <vector>
using namespace std;
int main(){ int L,m; if(!(cin>>L>>m)) return 0; vector<int> removed(L+1,0); for(int i=0;i<m;i++){ int l,r; cin>>l>>r; for(int p=l;p<=r;p++) removed[p]=1; } int ans=0; for(int p=0;p<=L;p++) if(!removed[p]) ans++; cout<<ans<<'\n'; return 0; }
